#[reducer]
pub fn publish_spell_definitions(ctx: &ReducerContext) -> Result<(), String> {
    sync_spell_definitions(ctx);
    Ok(())
}

pub(crate) fn sync_spell_definitions(ctx: &ReducerContext) {
    let expected: HashSet<String> = spell_definitions()
        .iter()
        .map(|definition| definition.kind.as_str().to_string())
        .collect();

    for definition in spell_definitions() {
        let key = definition.kind.as_str().to_string();
        let mut row = SpellDefinition {
            kind: key.clone(),
            cooldown_ms: definition.cooldown.as_millis() as u64,
            uses_global_cooldown: definition.uses_global_cooldown,
            global_cooldown_ms: if definition.uses_global_cooldown {
                definition.global_cooldown.as_millis() as u64
            } else {
                0
            },
            cast_time_ms: definition.cast_time.as_millis() as u64,
            behavior: definition.behavior.as_str().to_string(),
            targeting: definition.targeting.as_str().to_string(),
            target_audience: definition.target_audience.as_str().to_string(),
            requires_target: definition.requires_target,
            requires_target_los: definition.requires_target_los,
            aim_radius: definition.aim_radius.unwrap_or(0.0),
            has_aim_radius: definition.aim_radius.is_some(),
            speed: definition.speed,
            max_distance: definition.max_distance,
            damage: definition.damage,
            damage_type: definition.damage_type.as_str().to_string(),
            spawn_forward: definition.spawn_forward,
            spawn_height: definition.spawn_height,
            turn_rate: definition.turn_rate,
            update_interval: definition.update_interval,
            duration: definition.duration,
            radius: definition.radius,
            projectile_radius: definition.projectile_radius,
            root_duration_ms: 0,
            has_root_duration: false,
            status_stack_group: definition
                .status_stack_group
                .as_deref()
                .unwrap_or("")
                .to_string(),
            has_status_stack_group: definition.status_stack_group.is_some(),
            block_behavior: definition.block_behavior.as_str().to_string(),
            primary_resource_cost: definition.primary_resource_cost.max(0.0),
            generates_primary_resource_on_cast: definition.generates_primary_resource_on_cast,
        };

        if let Some(existing) = ctx.db.spell_definition().kind().find(key) {
            row.kind = existing.kind;
            ctx.db.spell_definition().kind().update(row);
        } else {
            ctx.db.spell_definition().insert(row);
        }
    }

    let stale: Vec<String> = ctx
        .db
        .spell_definition()
        .iter()
        .map(|row| row.kind)
        .filter(|kind| !expected.contains(kind))
        .collect();
    for kind in stale {
        ctx.db.spell_definition().kind().delete(kind);
    }
}
